        .filter(Boolean)
        .join(' ');
    return (<Drawer closable={closable} maskClosable={maskClosable} aria-label={ariaLabel} aria-labelledby={titleId} defaultSize={initialWidth} destroyOnHidden={destroyOnClose} extra={extra} footer={footer} maxSize={maxWidth} open={open} placement="right" resizable={{
            onResize: (nextWidth) => {
                updateWidth(nextWidth);
            }
        }} rootClassName={resolvedRootClassName} size={width} styles={{
            dragger: {
                left: NATIVE_DRAGGER_OFFSET,
                width: NATIVE_DRAGGER_HIT_WIDTH
            },
            wrapper: {
                minWidth: `min(${minWidth}px, ${viewportWidth})`,
                ...(viewportGutter > 0 ? { maxWidth: viewportWidth } : {})
            }
        }} title={<span id={titleId}>{title}</span>} zIndex={zIndex} onClose={onClose}>
      <div className={['resizable-drawer__body', bodyClassName]
            .filter(Boolean)
            .join(' ')}>
        <div aria-label={resizeLabel} aria-orientation="vertical" aria-valuemax={maxWidth} aria-valuemin={minWidth} aria-valuenow={width} className="resizable-drawer__keyboard-resize-handle" role="separator" tabIndex={0} onKeyDown={(event) => {
            if (event.key === 'ArrowLeft') {
                event.preventDefault();
                updateWidth(width + 40);
            }
            else if (event.key === 'ArrowRight') {
                event.preventDefault();
                updateWidth(width - 40);
            }
            else if (event.key === 'Home') {
                event.preventDefault();
                updateWidth(minWidth);
            }
            else if (event.key === 'End') {
                event.preventDefault();
                updateWidth(maxWidth);
            }
        }}/>
        <style>{".resizable-drawer__body {\n  position: relative;\n  min-height: 100%;\n}\n\n.resizable-drawer__keyboard-resize-handle {\n  position: absolute;\n  top: -24px;\n  bottom: -24px;\n  left: -32px;\n  z-index: 2;\n  width: 16px;\n  pointer-events: none;\n}\n\n.resizable-drawer__keyboard-resize-handle::after {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  left: 7px;\n  width: 2px;\n  content: \"\";\n  background: transparent;\n  transition: background-color 160ms ease;\n}\n\n.resizable-drawer__keyboard-resize-handle:focus-visible::after {\n  background: var(--color-primary);\n}\n"}</style>
        {children}
      </div>
    </Drawer>);
}
function clampWidth(width, minWidth, maxWidth) {
    return Math.min(maxWidth, Math.max(minWidth, width));
}
function pageWidthStorageKey() {
    if (typeof window === 'undefined') {
        return null;
    }
    return `${WIDTH_STORAGE_KEY_PREFIX}${window.location.pathname}`;
}
function resolveWidth(defaultWidth, minWidth, maxWidth, storageKey) {
    return clampWidth(readStoredWidth(storageKey) ?? defaultWidth, minWidth, maxWidth);
}
function readStoredWidth(storageKey) {
    if (!storageKey) {
        return null;
    }
    try {
        const storedWidth = window.localStorage.getItem(storageKey);
        if (!storedWidth?.trim()) {
            return null;
        }
        const width = Number(storedWidth);
        return Number.isFinite(width) ? width : null;
    }
    catch {
        return null;
    }
}
function writeStoredWidth(storageKey, width) {
    if (!storageKey) {
        return;
    }
    try {
        window.localStorage.setItem(storageKey, String(width));
    }
    catch {
        // Browser privacy settings must not disable local resizing.
    }
}

